diagnostic_evidence.quote:
Let \(\bar u\in C\bigl([0,T];L^{2}(\Omega)\bigr)\cap L^{2}\bigl(0,T;H^{1}(\Omega)\bigr)\) be the weak solution of  
		\begin{align*}
			\partial_{t}\bar u-\Delta\bar u+v(\bar u)&=f_{\bar\theta} \mathbf 1_{\omega} \quad\text{in }Q_{T},\\
			\bar u&=0 \quad\text{on }\Sigma_{T},\\
			\bar u(T)&=z_{0} \quad\text{in }\Omega .
		\end{align*}

Applying Gr\"onwall’s inequality to \eqref{eq:energy} gives, for any \(t\in[0,T]\),
		\begin{align*}
			\|\hat u(t)\|_{L^{2}(\Omega)}^{2}
			&\le e^{C_{0}(T-t)}\Bigl(
			\|\hat u(T)\|_{L^{2}(\Omega)}^{2}
			+C_{0}\!\int_{t}^{T}\!\bigl(\|R(s)\|_{L^{2}(\Omega)}^{2}
			+\|u_{\theta}(s)\|_{H^{1}(\partial\Omega)}^{2}\bigr)\, ds
			-\int_{t}^{T}\|\hat{u}\|^2_{H^1(\Omega)}ds\Bigr)

The controllability estimate of \cite[Theorem 1.6]{fernandez-cara_guerrero_2006} yields a constant \(C_{2}=C_{2}(Q_{T},\mathcal L_{v})\) such that
		\begin{equation}\label{eq:f_est1}
			\|f-f_{\bar\theta}\|_{L^{2}(q_{T})}
			\le C_{2}\,\|u_{0}-\bar u(0)\|_{L^{2}(\Omega)}
			\le C_{2}\bigl(\|u_{0}-u_{\theta}(0)\|_{L^{2}(\Omega)}
			+\|\hat u(0)\|_{L^{2}(\Omega)}\bigr).
		\end{equation}

failure_location.quote:
Then, there exists a constant $C>0$, depending only on $Q_T$, $v$, and $\lambda$ such that
		\begin{align*}
			\max_{t\in [0,T]}\|u(t)-u_\theta(t)\|^2_{L^2(\Omega)}
			+\|u-u_\theta\|^2_{L^2(0,T;H^1(\Omega))}
			+\|f-f_{\bar{\theta}}\|^2_{L^2(q_T)}
			\le C \delta.
		\end{align*}

diagnostic_evidence.quote:
The controllability estimate of \cite[Theorem 4.1]{zuazua2024exactcontrollabilitystabilizationwave} yields a constant \(C_3 = C_3 (Q_{T},\mathcal L_{v})\) such that
		\begin{align*}\label{eq:f_est2}
			\|f-f_{\bar{\theta}}\|_{L^2(q_T)}
			&\le C_3  (\|u_0-\bar{u}(0)\|_{H^1(\Omega)}+\|u_1-\partial_t \bar{u}(0)\|_{L^2(\Omega)})\\
			&\le C_3  (\|u_0-u_{\theta}(0)\|_{H^1(\Omega)}+\|u_1-\partial_t u_{\theta}(0)\|_{L^2(\Omega)}+\|\hat{u}(0)\|_{H^1(\Omega)}+\|\partial_t \hat{u}(0)\|_{L^2(\Omega)})\nonumber.
		\end{align*}

failure_location.quote:
Then, there exists a constant $C>0$, depending only on $Q_T$, $v$, and $\lambda$ such that
		\begin{align*}
			\max_{t\in[0,T]}\bigl(\|u(t)-u_\theta(t)\|^2_{H^1(\Omega)}
			+\|\partial_t u(t)-\partial_t u_\theta(t)\|^2_{L^2(\Omega)}\bigr)
			+\|f-f_{\bar{\theta}}\|^2_{L^2(q_T)}
			\le C \delta.
		\end{align*}
